  assert.equal(taskBranchPrefix('canon-review/2026-09'), 'claudinite/canon-review/2026-09/');
  assert.ok(mintBranch('canon-review/2026-09', NOW, 'ab12cd').startsWith('claudinite/canon-review/2026-09/'));
});

// The trailer recogniser answers "which task wrote this", and on a shared pull
// request that is whichever task pushed last — so the caller offers it only for the
// default family, where the two questions are the same one.
