// Two tasks, one pull request: the second task's run resolves the family the first
// one's commits are sitting on, and amends it. The head commit names the OTHER
// task, which is exactly why the trailer is not consulted here.
test('a shared family amends the pull request a sibling task opened, reading no head commits', async () => {
  const pulls = [pull(40, 'claudinite/canon-review/2026-09/2026-09-02-aaa', 'abc'), pull(41, 'feature/x', 'def')];
  const { gh, calls } = fakeGitHub({
    pulls, heads: { abc: 'Claudinite: promote\n\nClaudinite-Task: claudinite-canon-curation/growth-promote\n' }, mergeable: { 40: [true] },
  });
  const t = await resolve(gh, 'amend_existing_or_create_new_pr', { family: 'canon-review/2026-09' });
  assert.equal(t.mode, 'amend');
  assert.equal(t.pr, 40);
  assert.deepEqual(calls.filter((c) => c.startsWith('GET /repos/o/r/commits/')), [],
    'a shared family is settled by the branch prefix, so no head commit is read to ask which task wrote one');
});

// The default family is the task id, so a run that declares no name behaves as it
// always did — the property that lets every existing declaration through unchanged.
test('no family declared is the task id, and the trailer recogniser still answers', async () => {
  const pulls = [pull(12, 'claudinite/update-2026-09-02-xyz', 'abc')];
  const { gh } = fakeGitHub({ pulls, heads: { abc: `Claudinite-Task: ${TASK}\n` }, mergeable: { 12: [true] } });
  assert.equal((await resolve(gh, 'amend_existing_or_create_new_pr')).pr, 12);
  assert.equal((await resolve(gh, 'amend_existing_or_create_new_pr', { family: TASK })).pr, 12);
});
