import pathlib, re
p = pathlib.Path('packs/claudinite-tasks/task-contract.mjs')
t = p.read_text()
start = t.index("// THE PULL REQUEST A TASK NAMES (#1950).")
end = t.index("// The retired scope vocabulary.")
new = '''// THE PULL REQUEST A TASK WORKS ON (#1950). The target seam recognises a task's
// pull requests by a branch family; `pr_name` is what a task calls that family, so
// two tasks declaring the same one land on the same standing pull request and a
// `request` task can state where it will land before it runs. Absent, the family IS
// the task id — the shape every declaration written before this had, which is why
// nothing changes by passing through here.
//
// A literal name, never a pattern: nothing expands, and nothing is matched against
// an existing pull request's text. Two declarations share a pull request when they
// carry the same string, and that is the whole of it.
export const taskPrName = (decl, taskId) => {
  const declared = decl?.pr_name;
  return typeof declared === 'string' && declared.trim() !== '' ? declared.trim() : taskId;
};

// A family is path-shaped, because it becomes one: `claudinite/<family>/<leaf>`.
// Segments carry no traversal and no whitespace — a name is a branch prefix before
// it is anything else.
const PR_NAME_SEGMENT = /^[A-Za-z0-9._-]+$/;

// What is wrong with a declared name, or null. SHAPE ONLY: what the name means
// beside this task's other fields is nothing — a task's properties do not read each
// other — so a name never constrains, or is constrained by, the outcome it is
// carried with or the policy the run may merge under.
export function prNameProblem(prName) {
  if (typeof prName !== 'string' || prName.trim() === '') return 'it is not a non-empty string';
  if (prName !== prName.trim()) return 'it is padded with whitespace';
  const segments = prName.split('/');
  if (segments.some((s) => s === '')) return 'it has an empty path segment';
  if (segments.some((s) => s === '.' || s === '..')) return 'it traverses the branch namespace';
  if (!segments.every((s) => PR_NAME_SEGMENT.test(s))) return 'a segment is not letters, digits, ".", "_" or "-"';
  return null;
}

'''
