old_start = t.index('  // pr_name — the family this task\'s pull requests are recognised by (#1950).')
old_end = t.index('  // agent_instructions — REQUIRED for an agentic task')
new_block = '''  // pr_name — the family this task's pull requests are recognised by (#1950).
  // Shape, and nothing else: no other declared field changes what a name means, and
  // a name changes nothing about any other field.
  if (decl.pr_name !== undefined) {
    const problem = prNameProblem(decl.pr_name);
    if (problem) {
      bad(`"pr_name" ${JSON.stringify(decl.pr_name)} is not a legal name: ${problem}`,
        'write a branch-shaped name — letters, digits, ".", "_", "-", "/" between segments, e.g. "canon-review"');
    }
  }
'''
p.write_text(t[:old_start] + new_block + t[old_end:])
